window.QBANK = window.QBANK || {};
window.QBANK["smp-bahasa-inggris"] = {
  level: "SMP", subject: "Bahasa Inggris", duration: 900,
  questions: [
    { q: "She ___ to school every day.", options: ["go", "goes", "going", "gone"], answer: 1, solution: "Langkah 1: keterangan \"every day\" menandakan simple present tense (kebiasaan). Langkah 2: subjek \"she\" adalah orang ketiga tunggal. Langkah 3: kata kerja untuk orang ketiga tunggal ditambah -es, sehingga go menjadi goes." },
    { q: "They ___ football every Sunday.", options: ["play", "plays", "playing", "played"], answer: 0, solution: "Langkah 1: keterangan \"every Sunday\" menandakan simple present tense. Langkah 2: subjek \"they\" adalah jamak. Langkah 3: untuk subjek jamak dipakai kata kerja bentuk dasar tanpa -s, yaitu play." },
    { q: "Read the text: \"Rina is a student. She gets up at 5 a.m. every day. She goes to school by bike.\" How does Rina go to school?", options: ["By car", "By bike", "By bus", "On foot"], answer: 1, solution: "Langkah 1: cari kalimat yang menjelaskan cara Rina pergi ke sekolah. Langkah 2: teks menulis \"She goes to school by bike.\" Langkah 3: \"by bike\" artinya naik sepeda, jadi jawabannya By bike." },
    { q: "The antonym of \"big\" is ....", options: ["Large", "Small", "Huge", "Tall"], answer: 1, solution: "Langkah 1: antonym artinya lawan kata. Langkah 2: kata \"big\" artinya besar. Langkah 3: lawan kata \"besar\" adalah \"small\" yang artinya kecil." },
    { q: "Yesterday, I ___ my homework.", options: ["do", "does", "did", "done"], answer: 2, solution: "Langkah 1: keterangan \"yesterday\" menandakan past tense (waktu lampau). Langkah 2: bentuk lampau dari kata kerja \"do\" adalah \"did\". Langkah 3: jadi kalimatnya menjadi \"Yesterday, I did my homework.\"" },
    { q: "There ___ two books on the table.", options: ["is", "are", "was", "be"], answer: 1, solution: "Langkah 1: perhatikan subjeknya, \"two books\" (jamak). Langkah 2: untuk subjek jamak dalam kalimat present dipakai \"are\". Langkah 3: \"was\" adalah bentuk lampau sehingga tidak tepat." },
    { q: "Read the text: \"My cat is named Miko. It is white and fluffy. It likes to drink milk.\" What does Miko like to drink?", options: ["Water", "Milk", "Juice", "Tea"], answer: 1, solution: "Langkah 1: pertanyaan menanyakan apa yang disukai Miko untuk diminum. Langkah 2: teks menulis \"It likes to drink milk.\" Langkah 3: jadi Miko suka minum susu, yaitu Milk." },
    { q: "She is ___ than her sister. (tall)", options: ["tall", "taller", "tallest", "more tall"], answer: 1, solution: "Langkah 1: kata \"than\" menandakan bentuk perbandingan (comparative degree). Langkah 2: kata sifat pendek seperti \"tall\" dibentuk perbandingannya dengan menambah -er. Langkah 3: jadi jawabannya adalah \"taller\"." },
    { q: "The book is ___ the table.", options: ["in", "on", "at", "under"], answer: 1, solution: "Langkah 1: buku terletak di permukaan meja. Langkah 2: preposisi untuk \"di atas permukaan\" adalah \"on\". Langkah 3: \"under\" artinya di bawah dan \"in\" artinya di dalam, keduanya tidak tepat." },
    { q: "___ you like some tea?", options: ["Do", "Would", "Are", "Did"], answer: 1, solution: "Langkah 1: kalimat ini adalah tawaran yang sopan dalam bahasa Inggris. Langkah 2: pola tawaran yang sopan memakai \"Would you like ...?\". Langkah 3: jadi jawabannya adalah \"Would\"." }
,
    { q: "Look! The baby ___.", options: ["cry", "cries", "is crying", "cried"], answer: 2, solution: "Langkah 1: kata 'Look!' menandakan kejadian sedang berlangsung saat ini. Langkah 2: untuk kejadian yang sedang berlangsung dipakai present continuous, yaitu to be + verb-ing. Langkah 3: subjek 'the baby' tunggal memakai 'is', jadi jawabannya 'is crying'." },
    { q: "She ___ go to school yesterday.", options: ["doesn't", "didn't", "isn't", "not"], answer: 1, solution: "Langkah 1: keterangan 'yesterday' menandakan past tense (waktu lampau). Langkah 2: bentuk negatif past tense memakai 'did not (didn't)' diikuti kata kerja bentuk dasar. Langkah 3: jadi kalimatnya 'She didn't go to school yesterday'." },
    { q: "I ___ visit my grandmother tomorrow.", options: ["visit", "will visit", "visited", "visiting"], answer: 1, solution: "Langkah 1: keterangan 'tomorrow' menandakan waktu yang akan datang (future). Langkah 2: pola future tense adalah 'will' + kata kerja bentuk dasar. Langkah 3: jadi jawabannya 'will visit'." },
    { q: "The cake ___ by my mother yesterday.", options: ["made", "is made", "was made", "makes"], answer: 2, solution: "Langkah 1: keterangan 'yesterday' menandakan past tense, dan subjek 'the cake' dikenai perbuatan (kalimat pasif). Langkah 2: pola passive voice past tense adalah 'was/were' + verb 3. Langkah 3: subjek tunggal memakai 'was', jadi jawabannya 'was made'." },
    { q: "English ___ in many countries.", options: ["speaks", "is spoken", "spoke", "speaking"], answer: 1, solution: "Langkah 1: subjek 'English' dikenai perbuatan (bahasa itu dituturkan orang), jadi kalimatnya pasif. Langkah 2: pola passive voice present tense adalah 'is/are' + verb 3. Langkah 3: subjek tunggal memakai 'is', jadi jawabannya 'is spoken'." },
    { q: "My house is ___ than yours. (big)", options: ["big", "bigger", "biggest", "more big"], answer: 1, solution: "Langkah 1: kata 'than' menandakan comparative degree (perbandingan). Langkah 2: kata sifat satu suku kata seperti 'big' dibentuk perbandingannya dengan menambah -er dan menggandakan konsonan akhir. Langkah 3: jadi jawabannya 'bigger'." },
    { q: "Mount Everest is the ___ mountain in the world. (high)", options: ["high", "higher", "highest", "most high"], answer: 2, solution: "Langkah 1: kata 'the' sebelum kata sifat menandakan superlative degree (tingkatan paling). Langkah 2: kata sifat pendek dibentuk superlatifnya dengan menambah -est. Langkah 3: jadi jawabannya 'highest'." },
    { q: "If it rains, we ___ at home.", options: ["stay", "will stay", "would stay", "stayed"], answer: 1, solution: "Langkah 1: pola 'If + present, ...' adalah conditional sentence type 1. Langkah 2: induk kalimat conditional type 1 memakai 'will' + kata kerja bentuk dasar. Langkah 3: jadi jawabannya 'will stay'." },
    { q: "If you study hard, you ___ the exam.", options: ["pass", "will pass", "would pass", "passed"], answer: 1, solution: "Langkah 1: anak kalimat 'If you study hard' memakai present tense, jadi ini conditional type 1. Langkah 2: induk kalimatnya memakai 'will' + kata kerja bentuk dasar. Langkah 3: jadi jawabannya 'will pass'." },
    { q: "Read the text: 'Last Sunday, my family and I went to the beach. We swam and played with sand. We were very happy.' When did the writer go to the beach?", options: ["Last Saturday", "Last Sunday", "Yesterday", "Last month"], answer: 1, solution: "Langkah 1: pertanyaan menanyakan kapan penulis pergi ke pantai. Langkah 2: kalimat pertama teks menulis 'Last Sunday, my family and I went to the beach.' Langkah 3: jadi jawabannya Last Sunday." },
    { q: "Read the text: 'Last Sunday, my family and I went to the beach. We swam and played with sand.' What did they do at the beach?", options: ["They fished", "They swam and played with sand", "They camped", "They surfed"], answer: 1, solution: "Langkah 1: pertanyaan menanyakan kegiatan mereka di pantai. Langkah 2: teks menulis 'We swam and played with sand.' Langkah 3: jadi jawabannya 'They swam and played with sand'." },
    { q: "Read the text: 'Borobudur is the biggest Buddhist temple in the world. It is located in Magelang, Central Java.' Where is Borobudur located?", options: ["Yogyakarta", "Magelang, Central Java", "Bali", "Jakarta"], answer: 1, solution: "Langkah 1: pertanyaan menanyakan lokasi Candi Borobudur. Langkah 2: teks menulis 'It is located in Magelang, Central Java.' Langkah 3: jadi jawabannya Magelang, Central Java." },
    { q: "The synonym of 'happy' is ....", options: ["Sad", "Glad", "Angry", "Tired"], answer: 1, solution: "Langkah 1: synonym artinya persamaan kata. Langkah 2: kata 'happy' artinya senang atau gembira. Langkah 3: kata yang maknanya sama adalah 'glad'." },
    { q: "A person who teaches students at school is a ....", options: ["Doctor", "Teacher", "Farmer", "Driver"], answer: 1, solution: "Langkah 1: perhatikan pekerjaannya, yaitu mengajar siswa di sekolah. Langkah 2: doctor mengobati orang sakit, farmer bertani, dan driver mengemudi. Langkah 3: orang yang mengajar disebut 'teacher'." },
    { q: "There ___ a cat under the chair yesterday.", options: ["is", "are", "was", "were"], answer: 2, solution: "Langkah 1: keterangan 'yesterday' menandakan past tense. Langkah 2: perhatikan subjeknya, 'a cat' (tunggal). Langkah 3: untuk subjek tunggal dalam past tense dipakai 'was'." },
    { q: "'___ did you go last night?' – 'I went to the cinema.'", options: ["When", "Where", "What", "Who"], answer: 1, solution: "Langkah 1: jawaban 'I went to the cinema' menunjukkan sebuah tempat. Langkah 2: kata tanya untuk menanyakan tempat adalah 'where'. Langkah 3: 'when' untuk waktu, 'what' untuk benda, dan 'who' untuk orang." },
    { q: "This is ___ book. (I)", options: ["me", "my", "mine", "I"], answer: 1, solution: "Langkah 1: kata yang dibutuhkan adalah kata ganti kepemilikan yang diletakkan sebelum kata benda. Langkah 2: 'me' adalah kata ganti objek, 'mine' dipakai tanpa kata benda sesudahnya, dan 'I' adalah subjek. Langkah 3: bentuk yang tepat sebelum kata 'book' adalah 'my'." },
    { q: "There isn't ___ sugar in the jar.", options: ["many", "much", "a few", "few"], answer: 1, solution: "Langkah 1: kata 'sugar' termasuk uncountable noun (kata benda yang tidak dapat dihitung). Langkah 2: untuk uncountable noun dalam kalimat negatif dipakai 'much'. Langkah 3: 'many', 'a few', dan 'few' hanya dipakai untuk countable noun." },
    { q: "You ___ wash your hands before eating.", options: ["should", "will be", "are", "does"], answer: 0, solution: "Langkah 1: kalimat ini berisi anjuran atau saran. Langkah 2: modal yang dipakai untuk memberi saran adalah 'should' + kata kerja bentuk dasar. Langkah 3: jadi jawabannya 'should'." },
    { q: "She ___ a letter last night.", options: ["writes", "wrote", "written", "writing"], answer: 1, solution: "Langkah 1: keterangan 'last night' menandakan past tense. Langkah 2: bentuk lampau dari kata kerja 'write' adalah 'wrote' (kata kerja tak beraturan). Langkah 3: jadi kalimatnya 'She wrote a letter last night'." },
    { q: "Read the text: \"Once upon a time, there lived a hungry fox in a forest. One hot afternoon, he saw some juicy grapes hanging from a tall vine. He jumped again and again, but he could not reach them. Finally, he gave up and walked away.\" Which sentence is the orientation of the story?", options: ["'Once upon a time, there lived a hungry fox in a forest.'", "'One hot afternoon, he saw some juicy grapes hanging from a tall vine.'", "'He jumped again and again, but he could not reach them.'", "'Finally, he gave up and walked away.'"], answer: 0, solution: "Langkah 1: orientation adalah bagian pembuka teks naratif yang memperkenalkan tokoh, tempat, dan waktu. Langkah 2: kalimat 'Once upon a time, there lived a hungry fox in a forest' memperkenalkan tokoh (a hungry fox), tempat (in a forest), dan waktu (once upon a time). Langkah 3: jadi kalimat tersebut merupakan orientation." },
    { q: "In the fable 'The Hungry Fox', the fox jumps again and again to reach the grapes but he fails. This part of the story is called the ....", options: ["orientation", "resolution", "complication", "re-orientation"], answer: 2, solution: "Langkah 1: ingat struktur teks naratif: orientation, complication, resolution. Langkah 2: bagian ketika tokoh menghadapi masalah atau konflik disebut complication. Langkah 3: rubah yang gagal meraih anggur adalah masalah dalam cerita, jadi bagian ini disebut complication." },
    { q: "Read the legend: \"Long ago in West Sumatra, there lived a poor widow with her son, Malin Kundang. He grew up and became a rich merchant in a big city. Years later, he returned home, but he was ashamed of his old mother and refused to admit she was his mother. His heartbroken mother cursed him, and Malin Kundang turned into stone.\" Which sentence is the resolution of the story?", options: ["Malin Kundang went to a big city.", "He refused to admit his mother.", "There lived a poor widow with her son.", "His mother cursed him, and Malin Kundang turned into stone."], answer: 3, solution: "Langkah 1: resolution adalah bagian penutup teks naratif yang berisi penyelesaian masalah. Langkah 2: masalah dalam legenda ini adalah Malin Kundang yang durhaka kepada ibunya. Langkah 3: penyelesaian masalahnya adalah ia dikutuk menjadi batu, jadi kalimat terakhir merupakan resolution." },
    { q: "What is the moral value of the legend of Malin Kundang?", options: ["Be rich and successful.", "Never be ashamed of your parents; respect and love them.", "Travel to big cities to become rich.", "Do not return to your village."], answer: 1, solution: "Langkah 1: moral value adalah pesan baik yang dapat dipetik dari sebuah cerita. Langkah 2: Malin Kundang mendapat hukuman karena malu mengakui dan durhaka kepada ibunya. Langkah 3: pesan dari cerita ini adalah jangan pernah malu terhadap orang tua; hormati dan sayangilah mereka." },
    { q: "Dina said, 'I like this book.' Dina said that she ___ that book.", options: ["likes", "like", "liked", "will like"], answer: 2, solution: "Langkah 1: kalimat ini adalah reported speech (kalimat tidak langsung). Langkah 2: kata kerja pada kalimat langsung mengalami pergeseran waktu ke bentuk lampau: like menjadi liked. Langkah 3: jadi kalimatnya 'Dina said that she liked that book'." },
    { q: "Rudi said, 'I bought this pen yesterday.' Rudi said that he had bought ___ pen the day before.", options: ["that", "this", "these", "those"], answer: 0, solution: "Langkah 1: dalam reported speech, kata penunjuk yang dekat dengan pembicara berubah menjadi yang jauh. Langkah 2: kata 'this' (ini) berubah menjadi 'that' (itu). Langkah 3: jadi kalimatnya 'Rudi said that he had bought that pen the day before'." },
    { q: "The room ___ cleaned every day. (must)", options: ["must clean", "must be cleaned", "must cleaned", "must cleaning"], answer: 1, solution: "Langkah 1: subjek 'the room' dikenai perbuatan, jadi kalimatnya pasif. Langkah 2: pola modal passive adalah modal + be + verb 3. Langkah 3: jadi bentuk yang tepat adalah 'must be cleaned'." },
    { q: "The bridge ___ when the storm came. (repair)", options: ["was repaired", "is being repaired", "has been repaired", "was being repaired"], answer: 3, solution: "Langkah 1: subjek 'the bridge' dikenai perbuatan dan kejadiannya sedang berlangsung di masa lampau ('when the storm came'). Langkah 2: pola past continuous passive adalah was/were + being + verb 3. Langkah 3: subjek tunggal memakai 'was', jadi jawabannya 'was being repaired'." },
    { q: "If I ___ rich, I would travel around the world.", options: ["am", "were", "will be", "have been"], answer: 1, solution: "Langkah 1: pola 'If + past tense, ... would ...' adalah conditional sentence type 2 (pengandaian). Langkah 2: pada conditional type 2, to be yang dipakai untuk semua subjek adalah 'were'. Langkah 3: jadi jawabannya 'were'." },
    { q: "If she studied harder, she ___ pass the exam.", options: ["will", "can", "would", "shall"], answer: 2, solution: "Langkah 1: anak kalimat 'If she studied harder' memakai past tense, jadi ini conditional type 2. Langkah 2: induk kalimat conditional type 2 memakai 'would' + kata kerja bentuk dasar. Langkah 3: jadi jawabannya 'would'." },
    { q: "Rani is the ___ intelligent student in the class.", options: ["more", "intelligentest", "very", "most"], answer: 3, solution: "Langkah 1: kata 'the' sebelum kata sifat menandakan superlative degree (tingkatan paling). Langkah 2: kata sifat yang panjang (lebih dari dua suku kata) seperti 'intelligent' dibentuk superlatifnya dengan 'most'. Langkah 3: jadi jawabannya 'most'." },
    { q: "This test is ___ than the previous one. (difficult)", options: ["more difficult", "difficultest", "most difficult", "difficulter"], answer: 0, solution: "Langkah 1: kata 'than' menandakan comparative degree (perbandingan). Langkah 2: kata sifat yang panjang seperti 'difficult' dibentuk perbandingannya dengan 'more', bukan dengan -er. Langkah 3: jadi jawabannya 'more difficult'." },
    { q: "Read the text: 'Last holiday, I visited my grandmother in the village. We picked mangoes in her garden and cooked traditional food together. It was an unforgettable holiday.' The purpose of the text is to ....", options: ["describe grandmother's village", "explain how to cook traditional food", "retell the writer's past experience", "persuade readers to visit villages"], answer: 2, solution: "Langkah 1: perhatikan isi teks yang menceritakan pengalaman liburan penulis di masa lalu. Langkah 2: teks yang menceritakan kembali pengalaman masa lalu disebut recount text. Langkah 3: tujuan recount text adalah menceritakan kembali pengalaman penulis, yaitu 'retell the writer's past experience'." },
    { q: "Read the text: 'How to Make Fried Rice. Ingredients: rice, egg, oil, salt. Steps: First, heat the oil. Next, fry the egg. Then, add the rice and salt. Finally, stir well and serve.' The text above is a procedure text because it ....", options: ["retells a past event", "tells how to do something through goal, materials, and steps", "describes a beautiful place", "tells a fictional story"], answer: 1, solution: "Langkah 1: ingat ciri teks prosedur: berisi cara melakukan sesuatu. Langkah 2: teks memuat tujuan (How to Make Fried Rice), bahan (Ingredients), dan langkah-langkah (Steps). Langkah 3: jadi teks tersebut adalah procedure text karena menjelaskan cara melakukan sesuatu melalui goal, materials, dan steps." },
    { q: "'___ do you think of my new haircut?'", options: ["What", "How", "Why", "When"], answer: 0, solution: "Langkah 1: kalimat ini meminta pendapat orang lain (asking opinion). Langkah 2: ungkapan baku untuk menanyakan pendapat adalah 'What do you think of ...?'. Langkah 3: jadi kata tanya yang tepat adalah 'What'." },
    { q: "'I think the movie was boring.' The sentence is an expression of ....", options: ["invitation", "congratulation", "asking opinion", "giving opinion"], answer: 3, solution: "Langkah 1: perhatikan ungkapan 'I think' yang menyatakan pendapat pembicara. Langkah 2: menyatakan pendapat sendiri disebut giving opinion, sedangkan menanyakan pendapat disebut asking opinion. Langkah 3: jadi kalimat tersebut adalah expression of giving opinion." },
    { q: "Which expression is used to invite someone?", options: ["I am very happy for you.", "Would you like to come to my birthday party?", "Good luck on your exam!", "Can you help me?"], answer: 1, solution: "Langkah 1: undangan (invitation) adalah ajakan kepada seseorang untuk menghadiri suatu acara. Langkah 2: ungkapan sopan untuk mengundang adalah 'Would you like to ...?'. Langkah 3: pilihan B mengajak datang ke pesta ulang tahun, jadi merupakan invitation." },
    { q: "Your friend won an English speech contest. You say: '___'", options: ["Congratulations on your achievement!", "Get well soon!", "I'm sorry to hear that.", "Happy birthday!"], answer: 0, solution: "Langkah 1: teman memenangkan lomba, jadi ungkapan yang tepat adalah ucapan selamat (congratulation). Langkah 2: 'Get well soon' untuk orang sakit, 'I'm sorry to hear that' untuk kabar buruk, dan 'Happy birthday' untuk ulang tahun. Langkah 3: ucapan selamat atas prestasi adalah 'Congratulations on your achievement!'." },
    { q: "The synonym of 'ancient' is ....", options: ["Modern", "New", "Old", "Young"], answer: 2, solution: "Langkah 1: synonym artinya persamaan kata. Langkah 2: kata 'ancient' artinya kuno atau sangat tua. Langkah 3: kata yang maknanya sama adalah 'old'." },
    { q: "The flood caused ___ damage to the village because the water rose very ___. (enormous / rapid)", options: ["enormously – rapid", "enormous – rapidly", "enormous – rapid", "enormously – rapidly"], answer: 1, solution: "Langkah 1: kata pertama menerangkan kata benda 'damage', jadi harus kata sifat (adjective): 'enormous'. Langkah 2: kata kedua menerangkan kata kerja 'rose', jadi harus kata keterangan (adverb): 'rapidly'. Langkah 3: pasangan yang tepat adalah 'enormous – rapidly'." },
    { q: "My father ___ in a bank.", options: ["work", "working", "worked", "works"], answer: 3, solution: "1. Kalimat ini menyatakan pekerjaan yang rutin, jadi memakai simple present tense. 2. Subjek \"my father\" adalah orang ketiga tunggal. 3. Kata kerja untuk subjek tunggal ditambah -s, jadi jawabannya \"works\". \"work\" untuk subjek jamak, \"working\" butuh to be, dan \"worked\" adalah bentuk past tense." },
    { q: "We ___ our teeth twice a day.", options: ["brush", "brushes", "brushing", "brushed"], answer: 0, solution: "1. Keterangan \"twice a day\" menandakan simple present tense. 2. Subjek \"we\" adalah jamak. 3. Kata kerja untuk subjek jamak tidak ditambah -s, jadi jawabannya \"brush\". \"brushes\" hanya untuk subjek tunggal, \"brushing\" butuh to be, dan \"brushed\" adalah past tense." },
    { q: "The sun ___ in the east.", options: ["rise", "rising", "rose", "rises"], answer: 3, solution: "1. Ini fakta umum yang selalu benar, jadi memakai simple present tense. 2. Subjek \"the sun\" adalah orang ketiga tunggal. 3. Kata kerja ditambah -s menjadi \"rises\". \"rise\" untuk subjek jamak, \"rising\" butuh to be, dan \"rose\" adalah past tense." },
    { q: "Cats ___ milk.", options: ["like", "likes", "liking", "liked"], answer: 0, solution: "1. Ini kebiasaan umum, jadi memakai simple present tense. 2. Subjek \"cats\" adalah jamak. 3. Kata kerja tidak ditambah -s untuk subjek jamak, jadi jawabannya \"like\". \"likes\" untuk subjek tunggal dan \"liked\" adalah past tense." },
    { q: "She ___ her grandparents every weekend.", options: ["visit", "visiting", "visited", "visits"], answer: 3, solution: "1. Keterangan \"every weekend\" menandakan simple present tense. 2. Subjek \"she\" adalah orang ketiga tunggal. 3. Kata kerja ditambah -s menjadi \"visits\". \"visit\" untuk subjek jamak, \"visiting\" butuh to be, dan \"visited\" adalah past tense." },
    { q: "Birds ___ to the south in winter.", options: ["fly", "flies", "flying", "flew"], answer: 0, solution: "1. Ini kebiasaan yang berulang setiap tahun, jadi simple present tense. 2. Subjek \"birds\" adalah jamak. 3. Kata kerja tidak ditambah -s, jadi jawabannya \"fly\". \"flew\" adalah past tense." },
    { q: "The shop ___ at 9 a.m. every day.", options: ["open", "opening", "opened", "opens"], answer: 3, solution: "1. Keterangan \"every day\" menandakan simple present tense. 2. Subjek \"the shop\" adalah orang ketiga tunggal. 3. Kata kerja ditambah -s menjadi \"opens\". \"open\" untuk subjek jamak, \"opening\" butuh to be, dan \"opened\" adalah past tense." },
    { q: "Listen! The teacher ___ now.", options: ["speaks", "are speaking", "spoke", "is speaking"], answer: 3, solution: "1. Kata \"Listen!\" dan \"now\" menandakan kejadian sedang berlangsung, jadi present continuous tense. 2. Rumusnya: to be (am/is/are) + verb-ing. 3. Subjek \"the teacher\" tunggal memakai \"is\", jadi jawabannya \"is speaking\". \"are speaking\" untuk subjek jamak, \"speaks\" itu simple present, dan \"spoke\" itu past tense." },
    { q: "The children ___ in the yard at the moment.", options: ["play", "plays", "played", "are playing"], answer: 3, solution: "1. Keterangan \"at the moment\" menandakan present continuous tense. 2. Subjek \"the children\" adalah jamak, jadi to be-nya \"are\". 3. Jawabannya \"are playing\". \"play\" itu simple present dan \"played\" itu past tense." },
    { q: "I ___ my homework right now.", options: ["do", "does", "did", "am doing"], answer: 3, solution: "1. Keterangan \"right now\" menandakan present continuous tense. 2. Subjek \"I\" selalu memakai to be \"am\". 3. Jawabannya \"am doing\". \"do\" itu simple present, \"does\" untuk subjek tunggal, dan \"did\" itu past tense." },
    { q: "She ___ a letter at the moment.", options: ["write", "writes", "wrote", "is writing"], answer: 3, solution: "1. Keterangan \"at the moment\" menandakan present continuous tense. 2. Subjek \"she\" memakai to be \"is\". 3. Jawabannya \"is writing\". \"write\" dan \"writes\" itu simple present, sedangkan \"wrote\" itu past tense." },
    { q: "Look! The dog ___ after the cat.", options: ["run", "runs", "ran", "is running"], answer: 3, solution: "1. Kata \"Look!\" menandakan kejadian sedang terjadi sekarang, jadi present continuous tense. 2. Subjek \"the dog\" tunggal memakai \"is\". 3. Jawabannya \"is running\". \"runs\" itu simple present dan \"ran\" itu past tense." },
    { q: "I ___ a great movie last night.", options: ["watch", "watches", "watched", "watching"], answer: 2, solution: "1. Keterangan \"last night\" menandakan simple past tense. 2. Kata kerja beraturan ditambah -ed untuk past tense. 3. Jawabannya \"watched\". \"watch\" itu present, \"watches\" untuk subjek tunggal present, dan \"watching\" butuh to be." },
    { q: "She ___ to Surabaya two days ago.", options: ["go", "goes", "gone", "went"], answer: 3, solution: "1. Keterangan \"two days ago\" menandakan simple past tense. 2. \"go\" adalah kata kerja tak beraturan: go - went - gone. 3. Jawabannya \"went\". \"gone\" adalah past participle yang harus didahului have/has." },
    { q: "We ___ football yesterday afternoon.", options: ["play", "plays", "playing", "played"], answer: 3, solution: "1. Keterangan \"yesterday afternoon\" menandakan simple past tense. 2. Bentuk past tense dari \"play\" adalah \"played\". 3. Jawabannya \"played\". \"plays\" untuk subjek tunggal present." },
    { q: "They ___ the museum last month.", options: ["visit", "visits", "visiting", "visited"], answer: 3, solution: "1. Keterangan \"last month\" menandakan simple past tense. 2. Bentuk past tense dari \"visit\" adalah \"visited\". 3. Jawabannya \"visited\". \"visits\" untuk subjek tunggal present." },
    { q: "He ___ his bike to school this morning.", options: ["ride", "rides", "rode", "ridden"], answer: 2, solution: "1. Keterangan \"this morning\" (pagi tadi) menandakan simple past tense. 2. \"ride\" adalah kata kerja tak beraturan: ride - rode - ridden. 3. Jawabannya \"rode\". \"ridden\" adalah past participle yang harus didahului have/has." },
    { q: "My mother ___ a cake for my birthday yesterday.", options: ["make", "makes", "made", "making"], answer: 2, solution: "1. Keterangan \"yesterday\" menandakan simple past tense. 2. \"make\" adalah kata kerja tak beraturan: make - made - made. 3. Jawabannya \"made\". \"makes\" untuk subjek tunggal present." },
    { q: "The students ___ the exam last week.", options: ["pass", "passes", "passed", "passing"], answer: 2, solution: "1. Keterangan \"last week\" menandakan simple past tense. 2. Bentuk past tense dari \"pass\" adalah \"passed\". 3. Jawabannya \"passed\". \"passing\" butuh to be." },
    { q: "At 8 o'clock last night, they ___ dinner when the lights went out.", options: ["have", "am having", "had", "were having"], answer: 3, solution: "1. Kejadian yang sedang berlangsung di masa lalu lalu disela kejadian lain (\"when the lights went out\") memakai past continuous tense. 2. Rumusnya: was/were + verb-ing; subjek \"they\" memakai \"were\". 3. Jawabannya \"were having\". \"had\" tidak menekankan kejadian sedang berlangsung." },
    { q: "While I was cooking, my brother ___ TV.", options: ["watch", "watches", "was watching", "is watching"], answer: 2, solution: "1. Kata \"while\" + past continuous di klausa pertama menandakan dua kejadian berlangsung bersamaan di masa lalu. 2. Subjek \"my brother\" tunggal memakai \"was\". 3. Jawabannya \"was watching\". \"is watching\" itu present continuous." },
    { q: "They ___ football when it started to rain.", options: ["play", "are playing", "played", "were playing"], answer: 3, solution: "1. Kejadian yang sedang berlangsung (main bola) disela kejadian lain (hujan mulai turun) memakai past continuous. 2. Subjek \"they\" jamak memakai \"were\". 3. Jawabannya \"were playing\". \"are playing\" itu present continuous." },
    { q: "She ___ a book at 9 p.m. yesterday.", options: ["read", "reads", "was reading", "is reading"], answer: 2, solution: "1. Waktu spesifik di masa lalu (\"at 9 p.m. yesterday\") untuk kejadian yang sedang berlangsung memakai past continuous. 2. Subjek \"she\" tunggal memakai \"was\". 3. Jawabannya \"was reading\". \"is reading\" itu present continuous." },
    { q: "I think it ___ rain tomorrow.", options: ["would", "shall", "is", "will"], answer: 3, solution: "1. Kata \"tomorrow\" menandakan masa depan, jadi simple future tense. 2. \"I think\" menunjukkan prediksi atau opini, yang memakai \"will\". 3. Jawabannya \"will\". \"would\" untuk pengandaian dan \"is\" tidak cocok dengan kata \"rain\"." },
    { q: "They ___ move to a new house next month.", options: ["move", "moves", "are going to move", "moving"], answer: 2, solution: "1. \"next month\" menandakan masa depan dan ini sebuah rencana, jadi memakai \"be going to\". 2. Subjek \"they\" memakai \"are\". 3. Jawabannya \"are going to move\". \"moves\" untuk subjek tunggal simple present." },
    { q: "She ___ help you with your homework.", options: ["will", "would", "wills", "is will"], answer: 0, solution: "1. Ini tawaran bantuan untuk masa depan, jadi memakai \"will\". 2. Setelah \"will\", kata kerja selalu bentuk dasar tanpa tambahan apa pun. 3. Jawabannya \"will\". \"wills\" dan \"is will\" bukan bentuk bahasa Inggris yang benar." },
    { q: "We ___ buy a new motorcycle next year.", options: ["buy", "buys", "are going to buy", "buying"], answer: 2, solution: "1. \"next year\" menandakan masa depan dan ini rencana, jadi memakai \"be going to\". 2. Subjek \"we\" memakai \"are\". 3. Jawabannya \"are going to buy\". \"buy\" tanpa to be tidak bisa berdiri sendiri sebagai predikat future." },
    { q: "Look at the clouds! It ___ rain soon.", options: ["will", "goes to", "going to", "is going to"], answer: 3, solution: "1. Ada bukti yang terlihat sekarang (awan mendung) untuk memprediksi masa depan, jadi memakai \"be going to\". 2. Subjek \"it\" memakai \"is\". 3. Jawabannya \"is going to\". \"will\" dipakai untuk prediksi tanpa bukti atau keputusan spontan." },
    { q: "I ___ never been to Bali.", options: ["have", "has", "had", "having"], answer: 0, solution: "1. Kata \"never\" untuk pengalaman sampai sekarang memakai present perfect tense. 2. Rumusnya: have/has + past participle (\"been\"). 3. Subjek \"I\" memakai \"have\", jadi jawabannya \"have\". \"has\" untuk subjek tunggal, \"had\" itu past perfect." },
    { q: "She ___ just finished her homework.", options: ["have", "had", "having", "has"], answer: 3, solution: "1. Kata \"just\" (baru saja) menandakan present perfect tense. 2. Rumusnya: have/has + past participle. 3. Subjek \"she\" tunggal memakai \"has\", jadi jawabannya \"has\". \"have\" untuk subjek jamak, I, dan you." },
    { q: "They ___ lived here since 2020.", options: ["have", "has", "are", "were"], answer: 0, solution: "1. Kata \"since 2020\" menandakan kejadian mulai di masa lalu dan berlanjut sampai sekarang: present perfect. 2. Subjek \"they\" memakai \"have\". 3. Jawabannya \"have\". \"are\" dan \"were\" tidak cocok dengan past participle \"lived\" di sini." },
    { q: "He ___ already eaten lunch.", options: ["have", "is", "was", "has"], answer: 3, solution: "1. Kata \"already\" menandakan present perfect tense. 2. Rumusnya: have/has + past participle (\"eaten\"). 3. Subjek \"he\" tunggal memakai \"has\", jadi jawabannya \"has\"." },
    { q: "The windows ___ every morning.", options: ["clean", "cleans", "are cleaned", "is cleaned"], answer: 2, solution: "1. Subjek \"the windows\" menerima aksi (dibersihkan), jadi kalimat pasif. 2. Keterangan \"every morning\" = simple present; rumus pasif: am/is/are + past participle. 3. Subjek jamak memakai \"are\", jadi jawabannya \"are cleaned\". \"is cleaned\" untuk subjek tunggal." },
    { q: "The letter ___ by the postman yesterday.", options: ["deliver", "delivers", "was delivered", "is delivered"], answer: 2, solution: "1. Ada frasa \"by the postman\" dan subjek menerima aksi, jadi kalimat pasif. 2. Keterangan \"yesterday\" = simple past; rumus pasif: was/were + past participle. 3. Subjek tunggal memakai \"was\", jadi jawabannya \"was delivered\"." },
    { q: "Rice ___ in this village.", options: ["grow", "grows", "is grown", "are grown"], answer: 2, solution: "1. Subjek \"rice\" menerima aksi (ditanam), jadi kalimat pasif. 2. Ini fakta umum = simple present pasif: is + past participle. 3. \"rice\" dianggap tunggal, jadi jawabannya \"is grown\". \"grows\" adalah kalimat aktif." },
    { q: "The thief ___ by the police last night.", options: ["caught", "is caught", "catch", "was caught"], answer: 3, solution: "1. Subjek \"the thief\" menerima aksi (ditangkap), jadi kalimat pasif. 2. \"last night\" = simple past; rumus pasif: was + past participle. 3. Past participle dari \"catch\" adalah \"caught\", jadi jawabannya \"was caught\". \"is caught\" itu present." },
    { q: "This bridge ___ in 2010.", options: ["built", "is built", "builds", "was built"], answer: 3, solution: "1. Jembatan menerima aksi (dibangun), jadi kalimat pasif. 2. Tahun 2010 sudah lewat = simple past; rumus pasif: was + past participle. 3. Past participle dari \"build\" adalah \"built\", jadi jawabannya \"was built\"." },
    { q: "These shirts ___ in Bandung.", options: ["make", "makes", "are made", "is made"], answer: 2, solution: "1. Subjek \"these shirts\" menerima aksi (dibuat), jadi kalimat pasif. 2. Ini fakta umum = simple present pasif: be + past participle. 3. Subjek jamak memakai \"are\" dan past participle dari \"make\" adalah \"made\", jadi jawabannya \"are made\"." },
    { q: "The floor ___ twice a week.", options: ["mop", "mops", "is mopped", "are mopped"], answer: 2, solution: "1. Subjek \"the floor\" menerima aksi (dipel), jadi kalimat pasif. 2. \"twice a week\" = simple present; subjek tunggal memakai \"is\". 3. Past participle dari \"mop\" adalah \"mopped\", jadi jawabannya \"is mopped\"." },
    { q: "The classroom ___ by the students now.", options: ["clean", "was cleaned", "cleans", "is being cleaned"], answer: 3, solution: "1. Subjek menerima aksi dan ada kata \"now\", jadi pasif bentuk present continuous. 2. Rumusnya: is/are + being + past participle. 3. Subjek tunggal memakai \"is\", jadi jawabannya \"is being cleaned\". \"was cleaned\" itu past." },
    { q: "An elephant is ___ than a horse.", options: ["big", "biggest", "more big", "bigger"], answer: 3, solution: "1. Kata \"than\" menandakan perbandingan (comparative degree). 2. Kata sifat satu suku kata ditambah -er; \"big\" menggandakan huruf g menjadi \"bigger\". 3. Jawabannya \"bigger\". \"more big\" salah karena kata sifat pendek tidak memakai more." },
    { q: "This is the ___ day of my life.", options: ["happy", "happier", "happiest", "more happy"], answer: 2, solution: "1. Kata \"the\" + perbandingan dengan semuanya (\"of my life\") menandakan superlative degree. 2. Kata sifat berakhiran konsonan + y berubah menjadi -iest: \"happiest\". 3. Jawabannya \"happiest\". \"happier\" itu comparative." },
    { q: "My bag is ___ than yours.", options: ["heavy", "heaviest", "more heavy", "heavier"], answer: 3, solution: "1. Kata \"than\" menandakan comparative degree. 2. Kata sifat berakhiran konsonan + y berubah menjadi -ier: \"heavier\". 3. Jawabannya \"heavier\". \"more heavy\" salah untuk kata sifat seperti ini." },
    { q: "Lake Toba is the ___ lake in Indonesia.", options: ["large", "larger", "largest", "more large"], answer: 2, solution: "1. Kata \"the\" + membandingkan dengan semua danau di Indonesia menandakan superlative degree. 2. Kata sifat satu suku kata ditambah -est: \"largest\". 3. Jawabannya \"largest\". \"larger\" itu comparative." },
    { q: "He is the ___ boy in the class.", options: ["tall", "taller", "tallest", "more tall"], answer: 2, solution: "1. Kata \"the\" + \"in the class\" menandakan superlative degree. 2. \"tall\" satu suku kata ditambah -est menjadi \"tallest\". 3. Jawabannya \"tallest\". \"more tall\" bukan bentuk yang benar." },
    { q: "Math is ___ than English for me.", options: ["difficult", "more difficult", "most difficult", "difficulter"], answer: 1, solution: "1. Kata \"than\" menandakan comparative degree. 2. Kata sifat panjang (tiga suku kata) memakai \"more\", bukan -er. 3. Jawabannya \"more difficult\". \"difficulter\" bukan kata yang benar." },
    { q: "A motorcycle is ___ than a bicycle.", options: ["fast", "faster", "fastest", "more fast"], answer: 1, solution: "1. Kata \"than\" menandakan comparative degree. 2. \"fast\" satu suku kata ditambah -er menjadi \"faster\". 3. Jawabannya \"faster\". \"more fast\" salah untuk kata sifat pendek." },
    { q: "If you leave now, you ___ the bus.", options: ["catch", "will catch", "caught", "would catch"], answer: 1, solution: "1. Ini conditional type 1: if + simple present, klausa utama memakai will. 2. Klausa if sudah memakai present (\"leave\"). 3. Klausa utama memakai \"will + verb\", jadi jawabannya \"will catch\". \"would catch\" itu untuk conditional type 2." },
    { q: "If we save money, we ___ a new bike.", options: ["buy", "will buy", "bought", "would buy"], answer: 1, solution: "1. Conditional type 1 memakai pola if + present, will + verb. 2. Klausa if memakai present (\"save\"). 3. Jawabannya \"will buy\". \"would buy\" untuk pengandaian type 2." },
    { q: "If you don't hurry, you ___ late.", options: ["are", "will be", "were", "would be"], answer: 1, solution: "1. Conditional type 1: klausa if memakai present (\"don't hurry\"). 2. Klausa utama memakai \"will\" + kata kerja dasar. 3. Jawabannya \"will be\". \"would be\" untuk conditional type 2." },
    { q: "We will go swimming if the weather ___ nice.", options: ["is", "will be", "was", "would be"], answer: 0, solution: "1. Conditional type 1: klausa utama memakai \"will\", maka klausa if harus simple present. 2. Subjek \"the weather\" tunggal memakai \"is\". 3. Jawabannya \"is\". \"will\" tidak boleh dipakai di dalam klausa if." },
    { q: "If they invite me, I ___ to the party.", options: ["go", "will go", "went", "would go"], answer: 1, solution: "1. Conditional type 1: if + present (\"invite\"), klausa utama memakai will. 2. Polanya: will + kata kerja dasar. 3. Jawabannya \"will go\". \"would go\" untuk type 2." },
    { q: "Students ___ wear uniforms at school.", options: ["must", "musts", "have", "has"], answer: 0, solution: "1. Ini aturan yang mewajibkan, jadi memakai modal \"must\". 2. Setelah modal, kata kerja selalu bentuk dasar tanpa -s atau -ing. 3. Jawabannya \"must\". \"musts\" bukan bentuk yang benar." },
    { q: "___ I borrow your pen, please?", options: ["Must", "Should", "May", "Have to"], answer: 2, solution: "1. Ini permintaan izin yang sopan, jadi memakai \"May\". 2. \"Must\" untuk kewajiban dan \"Should\" untuk saran, tidak cocok untuk meminta izin. 3. Jawabannya \"May\"." },
    { q: "You ___ eat too much candy. It's bad for your teeth.", options: ["should", "shouldn't", "mustn't to", "don't should"], answer: 1, solution: "1. Kalimat ini memberi nasihat agar tidak melakukan sesuatu. 2. \"shouldn't\" berarti sebaiknya jangan, sedangkan \"should\" berarti sebaiknya lakukan. 3. Jawabannya \"shouldn't\". \"mustn't to\" dan \"don't should\" bukan bentuk yang benar." },
    { q: "He ___ speak three languages.", options: ["can", "cans", "must to", "should to"], answer: 0, solution: "1. Ini menyatakan kemampuan, jadi memakai modal \"can\". 2. Setelah modal, kata kerja selalu bentuk dasar. 3. Jawabannya \"can\". \"cans\", \"must to\", dan \"should to\" bukan bentuk yang benar." },
    { q: "There ___ some milk in the fridge.", options: ["is", "are", "was", "were"], answer: 0, solution: "1. \"milk\" adalah kata benda tak terhitung (uncountable) dan dianggap tunggal. 2. Untuk benda tunggal memakai \"there is\". 3. Jawabannya \"is\". \"are\" dan \"were\" untuk benda jamak." },
    { q: "There ___ many students in the library now.", options: ["is", "are", "was", "were"], answer: 1, solution: "1. \"students\" adalah kata benda jamak. 2. Untuk benda jamak memakai \"there are\". 3. Jawabannya \"are\". \"is\" dan \"was\" untuk benda tunggal." },
    { q: "There ___ a big tree in front of my house.", options: ["is", "are", "was", "were"], answer: 0, solution: "1. \"a big tree\" adalah benda tunggal. 2. Untuk benda tunggal memakai \"there is\". 3. Jawabannya \"is\"." },
    { q: "I don't have ___ money left.", options: ["some", "any", "many", "a few"], answer: 1, solution: "1. Kalimat negatif memakai \"any\", bukan \"some\". 2. \"money\" tak terhitung, jadi \"many\" dan \"a few\" (khusus countable) salah. 3. Jawabannya \"any\"." },
    { q: "She bought ___ apples at the market.", options: ["much", "many", "a little", "any"], answer: 1, solution: "1. \"apples\" adalah kata benda countable jamak. 2. Untuk countable jamak dalam jumlah banyak memakai \"many\". 3. Jawabannya \"many\". \"much\" dan \"a little\" hanya untuk uncountable." },
    { q: "I need ___ help with my homework.", options: ["a few", "a little", "many", "a lot"], answer: 1, solution: "1. \"help\" adalah kata benda tak terhitung (uncountable). 2. Untuk uncountable yang sedikit memakai \"a little\". 3. Jawabannya \"a little\". \"a few\" hanya untuk countable." },
    { q: "Only ___ students came to class today.", options: ["a few", "a little", "much", "any"], answer: 0, solution: "1. \"students\" adalah countable jamak. 2. Untuk countable jamak yang sedikit memakai \"a few\". 3. Jawabannya \"a few\". \"a little\" dan \"much\" hanya untuk uncountable." },
    { q: "The cat is hiding ___ the bed.", options: ["on", "under", "in", "at"], answer: 1, solution: "1. Kucing bersembunyi di kolong tempat tidur, jadi preposisi tempat yang tepat adalah \"under\" (di bawah). 2. \"on\" berarti di atas permukaan, \"in\" berarti di dalam. 3. Jawabannya \"under\"." },
    { q: "My birthday is ___ June.", options: ["in", "on", "at", "of"], answer: 0, solution: "1. Untuk nama bulan memakai preposisi \"in\". 2. \"on\" untuk tanggal dan hari, \"at\" untuk jam tertentu. 3. Jawabannya \"in\"." },
    { q: "The school starts ___ 7 o'clock.", options: ["in", "on", "at", "by"], answer: 2, solution: "1. Untuk jam yang spesifik memakai preposisi \"at\". 2. \"in\" untuk bulan dan tahun, \"on\" untuk hari dan tanggal. 3. Jawabannya \"at\"." },
    { q: "She was born ___ 2012.", options: ["in", "on", "at", "since"], answer: 0, solution: "1. Untuk tahun memakai preposisi \"in\". 2. \"on\" untuk tanggal, \"at\" untuk jam, dan \"since\" berarti sejak. 3. Jawabannya \"in\"." },
    { q: "The ball is ___ the two boxes.", options: ["between", "behind", "under", "on"], answer: 0, solution: "1. \"between\" dipakai untuk sesuatu yang berada di antara dua benda. 2. \"behind\" berarti di belakang dan \"under\" berarti di bawah. 3. Jawabannya \"between\"." },
    { q: "This bag is ___. I bought it yesterday.", options: ["my", "mine", "me", "I"], answer: 1, solution: "1. Kata yang dibutuhkan adalah possessive pronoun yang berdiri sendiri di akhir kalimat. 2. \"mine\" berarti milik saya, sedangkan \"my\" harus diikuti kata benda (my bag). 3. Jawabannya \"mine\". \"me\" adalah object pronoun." },
    { q: "___ are my friends. They live near me.", options: ["This", "That", "These", "That one"], answer: 2, solution: "1. Subjeknya jamak (\"friends\"), jadi memakai demonstrative pronoun jamak. 2. Untuk yang dekat memakai \"these\", untuk yang jauh memakai \"those\". 3. Jawabannya \"These\". \"This\" dan \"That\" untuk tunggal." },
    { q: "She gave ___ a beautiful gift.", options: ["I", "my", "me", "mine"], answer: 2, solution: "1. Kata yang dibutuhkan adalah object pronoun sebagai objek dari kata kerja \"gave\". 2. Object pronoun untuk \"I\" adalah \"me\". 3. Jawabannya \"me\". \"my\" dan \"mine\" menunjukkan kepemilikan, bukan objek." },
    { q: "This is ___ pen, and that one is ___.", options: ["my / yours", "mine / your", "me / you", "I / mine"], answer: 0, solution: "1. Sebelum kata benda \"pen\" memakai possessive adjective: \"my\". 2. Di akhir kalimat tanpa kata benda memakai possessive pronoun: \"yours\". 3. Jawabannya \"my / yours\". \"mine\" tidak bisa dipakai sebelum kata benda." },
    { q: "___ did you buy at the market?", options: ["Who", "What", "Where", "When"], answer: 1, solution: "1. Pertanyaan menanyakan barang yang dibeli. 2. Untuk menanyakan benda memakai \"What\". 3. Jawabannya \"What\". \"Who\" untuk orang, \"Where\" untuk tempat, \"When\" untuk waktu." },
    { q: "___ is your English teacher?", options: ["Who", "Whose", "Whom", "What"], answer: 0, solution: "1. Pertanyaan menanyakan orang (guru). 2. Untuk menanyakan orang sebagai subjek memakai \"Who\". 3. Jawabannya \"Who\". \"Whose\" menanyakan kepemilikan." },
    { q: "___ will the meeting start?", options: ["Who", "Where", "What time", "Whose"], answer: 2, solution: "1. Yang ditanyakan adalah jam rapat dimulai. 2. Untuk menanyakan jam memakai \"What time\". 3. Jawabannya \"What time\". \"Where\" menanyakan tempat." },
    { q: "I wanted to go out, ___ it was raining.", options: ["and", "but", "so", "because"], answer: 1, solution: "1. Dua klausa bertentangan: ingin keluar tetapi hujan. 2. Konjungsi untuk pertentangan adalah \"but\". 3. Jawabannya \"but\". \"so\" untuk akibat dan \"because\" untuk alasan." },
    { q: "She studied hard ___ she passed the exam.", options: ["but", "although", "so", "or"], answer: 2, solution: "1. Klausa kedua adalah hasil atau akibat dari klausa pertama. 2. Konjungsi untuk akibat adalah \"so\". 3. Jawabannya \"so\". \"because\" dipakai jika urutannya dibalik (alasan dulu)." },
    { q: "___ I was walking home, I met an old friend.", options: ["When", "Because", "So", "But"], answer: 0, solution: "1. Klausa pertama menunjukkan waktu kejadian berlangsung. 2. Konjungsi untuk waktu adalah \"when\" atau \"while\". 3. Jawabannya \"When\". \"Because\" untuk alasan." },
    { q: "Sinta said, 'I am tired.' Sinta said that she ___ tired.", options: ["is", "was", "am", "were"], answer: 1, solution: "1. Reported speech: kalimat langsung diubah menjadi tidak langsung. 2. Tense mundur satu langkah: am/is (present) menjadi was (past). 3. Subjek \"I\" berubah menjadi \"she\", jadi jawabannya \"was\"." },
    { q: "Andi said, 'I will help you.' Andi said that he ___ help me.", options: ["would", "will", "shall", "can"], answer: 0, solution: "1. Reported speech: tense mundur satu langkah. 2. \"will\" berubah menjadi \"would\". 3. Kata ganti \"you\" berubah menjadi \"me\", jadi jawabannya \"would\"." },
    { q: "She asked me, 'Where do you live?' She asked me where I ___.", options: ["live", "lived", "living", "lives"], answer: 1, solution: "1. Reported question: tense mundur satu langkah dan tidak ada inversi. 2. \"do you live\" (present) berubah menjadi \"lived\" (past). 3. Jawabannya \"lived\"." },
    { q: "She sings ___.", options: ["beautiful", "beautifully", "beauty", "quietly"], answer: 1, solution: "1. Kata yang menjelaskan kata kerja \"sings\" adalah adverb (kata keterangan). 2. Adverb dibentuk dari adjective + -ly: \"beautifully\". 3. Jawabannya \"beautifully\". \"beautiful\" adalah adjective yang menjelaskan kata benda." },
    { q: "He is a ___ driver.", options: ["careful", "carefully", "care", "caringly"], answer: 0, solution: "1. Kata yang menjelaskan kata benda \"driver\" adalah adjective (kata sifat). 2. Adjective tidak ditambah -ly: \"careful\". 3. Jawabannya \"careful\". \"carefully\" adalah adverb yang menjelaskan kata kerja." },
    { q: "The baby slept ___.", options: ["quiet", "quietly", "quieter", "quietness"], answer: 1, solution: "1. Kata yang menjelaskan kata kerja \"slept\" adalah adverb. 2. Bentuk adverb dari \"quiet\" adalah \"quietly\". 3. Jawabannya \"quietly\". \"quieter\" itu comparative adjective." },
    { q: "I saw ___ elephant at the zoo.", options: ["a", "an", "the", "no article"], answer: 1, solution: "1. Kata benda tunggal yang belum spesifik memakai a/an. 2. \"elephant\" diawali bunyi vokal, jadi memakai \"an\". 3. Jawabannya \"an\". \"the\" untuk benda yang sudah spesifik." },
    { q: "She wants to be ___ doctor.", options: ["a", "an", "the", "no article"], answer: 0, solution: "1. Profesi yang belum spesifik memakai a/an. 2. \"doctor\" diawali bunyi konsonan, jadi memakai \"a\". 3. Jawabannya \"a\". \"an\" untuk bunyi vokal." },
    { q: "___ sun rises in the east.", options: ["A", "An", "The", "No article"], answer: 2, solution: "1. \"sun\" adalah benda yang hanya ada satu di dunia. 2. Benda yang unik dan sudah jelas memakai \"the\". 3. Jawabannya \"The\"." },
    { q: "The farmer has five ___.", options: ["sheep", "sheeps", "sheepes", "sheep's"], answer: 0, solution: "1. \"sheep\" adalah kata benda irregular: bentuk jamaknya tetap \"sheep\". 2. Tidak ditambah -s menjadi \"sheeps\". 3. Jawabannya \"sheep\"." },
    { q: "Neither of the boys ___ late.", options: ["is", "are", "were", "be"], answer: 0, solution: "1. \"Neither\" selalu dianggap tunggal. 2. Subjek tunggal memakai kata kerja bentuk tunggal \"is\". 3. Jawabannya \"is\". \"are\" dan \"were\" untuk subjek jamak." },
    { q: "The news ___ good today.", options: ["are", "is", "were", "have"], answer: 1, solution: "1. \"news\" terlihat jamak karena ada -s, tapi sebenarnya uncountable dan dianggap tunggal. 2. Subjek tunggal memakai \"is\". 3. Jawabannya \"is\"." },
    { q: "My sister and I ___ breakfast together.", options: ["has", "have", "haves", "is having"], answer: 1, solution: "1. Subjek \"my sister and I\" terdiri dari dua orang, jadi jamak. 2. Subjek jamak memakai \"have\", bukan \"has\". 3. Jawabannya \"have\". \"haves\" bukan bentuk yang benar." },
    { q: "Bread and butter ___ my favorite food.", options: ["are", "were", "is", "have"], answer: 2, solution: "1. \"bread and butter\" dianggap satu kesatuan hidangan, jadi diperlakukan sebagai subjek tunggal. 2. Subjek tunggal memakai \"is\". 3. Jawabannya \"is\"." },
    { q: "'No Parking' means you ___ park here.", options: ["must", "must not", "can", "should"], answer: 1, solution: "1. \"No Parking\" adalah rambu larangan. 2. Larangan memakai \"must not\" yang artinya tidak boleh. 3. Jawabannya \"must not\". \"can\" berarti boleh, kebalikan dari maknanya." },
    { q: "___ your hands before eating.", options: ["Wash", "Washes", "Washing", "To wash"], answer: 0, solution: "1. Ini kalimat perintah (imperative sentence). 2. Imperative memakai kata kerja bentuk dasar tanpa subjek. 3. Jawabannya \"Wash\". \"Washes\" memakai -s dan \"To wash\" bukan bentuk perintah." },
    { q: "'Keep off the grass' means ___.", options: ["walk on the grass", "don't step on the grass", "cut the grass", "water the grass"], answer: 1, solution: "1. \"Keep off the grass\" artinya jangan menginjak rumput. 2. Pilihan yang maknanya sama adalah \"don't step on the grass\". 3. Pilihan lain maknanya bertentangan atau berbeda." },

    { q: "Read the text: Last weekend, Andi went to his uncle's farm in the village. He fed the chickens and rode a buffalo. He returned home in the evening, feeling very happy. What did Andi do at the farm?", options: ["He fed the chickens and rode a buffalo", "He swam in the river", "He planted rice all day", "He visited the zoo"], answer: 0, solution: "1. Pertanyaan menanyakan apa yang dilakukan Andi di peternakan. 2. Teks menulis ia memberi makan ayam dan menunggang kerbau. 3. Jadi jawaban yang tepat adalah opsi pertama." },
    { q: "Read the text: Yesterday morning, Sinta went to the market with her mother. They bought vegetables, fish, and fruit. After that, they had breakfast at a small food stall. When did Sinta go to the market?", options: ["Yesterday afternoon", "Yesterday morning", "Last night", "This morning"], answer: 1, solution: "1. Pertanyaan menanyakan kapan Sinta pergi ke pasar. 2. Teks menulis yesterday morning, artinya kemarin pagi. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: During the school holiday, Budi visited his cousin in Bandung. They played football in the park and watched a movie at the cinema. Budi stayed there for three days. How long did Budi stay in Bandung?", options: ["One day", "Two days", "Three days", "One week"], answer: 2, solution: "1. Pertanyaan menanyakan berapa lama Budi tinggal di Bandung. 2. Teks menulis ia tinggal di sana selama tiga hari. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: Last month, our class went camping in the mountains. We set up tents, cooked noodles, and sang songs around the campfire. It was an unforgettable experience. What is the text about?", options: ["A football match", "A birthday party", "A school exam", "A camping trip in the mountains"], answer: 3, solution: "1. Pertanyaan menanyakan isi teks secara umum. 2. Teks menceritakan kegiatan berkemah di gunung: mendirikan tenda, memasak mi, dan bernyanyi di sekitar api unggun. 3. Jadi teks tersebut tentang perjalanan berkemah di gunung." },
    { q: "Read the text: Two days ago, Dewi lost her wallet at the bus stop. A kind old man found it and returned it to her. Dewi thanked him and gave him some snacks. Who returned Dewi's wallet?", options: ["A kind old man", "The bus driver", "Her teacher", "Her classmate"], answer: 0, solution: "1. Pertanyaan menanyakan siapa yang mengembalikan dompet Dewi. 2. Teks menulis seorang kakek yang baik hati menemukannya dan mengembalikannya. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: On Saturday, Rudi and his friends cleaned the beach near their village. They collected plastic bottles and trash for two hours. The beach looked much cleaner after that. What did Rudi and his friends do on Saturday?", options: ["They played volleyball", "They cleaned the beach", "They went fishing", "They built sandcastles"], answer: 1, solution: "1. Pertanyaan menanyakan apa yang dilakukan Rudi dan teman-temannya. 2. Teks menulis mereka membersihkan pantai dan mengumpulkan sampah selama dua jam. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: Last night, it rained very hard in my town. The streets were flooded and the electricity went out. We had dinner by candlelight. What happened last night?", options: ["There was a big festival", "The power stayed on", "It rained hard and the electricity went out", "Snow fell on the town"], answer: 2, solution: "1. Pertanyaan menanyakan apa yang terjadi tadi malam. 2. Teks menulis hujan turun sangat deras dan listrik padam. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: In January, Father took us to the zoo. We saw elephants, giraffes, and monkeys. My little sister loved the playful monkeys the most. Which animal did the little sister love the most?", options: ["The elephants", "The giraffes", "The tigers", "The playful monkeys"], answer: 3, solution: "1. Pertanyaan menanyakan hewan apa yang paling disukai adiknya. 2. Teks menulis adiknya paling suka monyet-monyet yang lucu. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: Yesterday, I helped my mother bake a chocolate cake for my brother's birthday. We mixed the flour, sugar, and eggs together. The cake smelled delicious. Why did the writer bake a chocolate cake?", options: ["For his brother's birthday", "For a school competition", "For the neighbors", "For a wedding party"], answer: 0, solution: "1. Pertanyaan menanyakan alasan penulis membuat kue cokelat. 2. Teks menulis kue itu dibuat untuk ulang tahun adik laki-lakinya. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: Last week, our school held a sports day. I joined the running race and finished second. My friend Toni won the long jump competition. What did the writer achieve in the running race?", options: ["First place", "Second place", "Third place", "He did not finish"], answer: 1, solution: "1. Pertanyaan menanyakan hasil penulis dalam lomba lari. 2. Teks menulis ia finis di posisi kedua. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: A month ago, I got a new bicycle from my parents. I learned to ride it in the park with my father. Now I can ride it to school every day. Who taught the writer to ride the bicycle?", options: ["His mother", "His friend", "His father", "His teacher"], answer: 2, solution: "1. Pertanyaan menanyakan siapa yang mengajari penulis naik sepeda. 2. Teks menulis ia belajar naik sepeda di taman bersama ayahnya. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: During the long holiday, we stayed at a hotel near the lake. In the morning we rented a small boat and rowed across the lake. The water was calm and the view was beautiful. What did they do in the morning?", options: ["They swam across the lake", "They climbed a hill", "They visited a museum", "They rented a boat and rowed across the lake"], answer: 3, solution: "1. Pertanyaan menanyakan apa yang mereka lakukan di pagi hari. 2. Teks menulis mereka menyewa perahu kecil dan mendayung melintasi danau. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: Mr. Hadi is our English teacher. He is tall and thin with short black hair. He always smiles and explains the lessons patiently. What does Mr. Hadi look like?", options: ["Tall and thin with short black hair", "Short and fat with long hair", "Tall and muscular with blond hair", "Old with a white beard"], answer: 0, solution: "1. Pertanyaan menanyakan penampilan Pak Hadi. 2. Teks menulis ia tinggi dan kurus dengan rambut hitam pendek. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: My rabbit, Puti, has soft white fur and long ears. She likes to eat carrots and hops around the garden every morning. What does Puti like to eat?", options: ["Fish", "Carrots", "Rice", "Bread"], answer: 1, solution: "1. Pertanyaan menanyakan makanan kesukaan Puti. 2. Teks menulis Puti suka makan wortel. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: Lake Toba is a large beautiful lake in North Sumatra. It has a big island called Samosir in the middle. Many tourists visit it every year. Where is Lake Toba located?", options: ["In West Java", "In Bali", "In North Sumatra", "In East Kalimantan"], answer: 2, solution: "1. Pertanyaan menanyakan lokasi Danau Toba. 2. Teks menulis Danau Toba ada di Sumatera Utara. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: My backpack is dark blue and has three pockets. It is made of strong fabric and is very comfortable to carry. How many pockets does the backpack have?", options: ["One", "Two", "Four", "Three"], answer: 3, solution: "1. Pertanyaan menanyakan jumlah kantong tas. 2. Teks menulis tas itu memiliki tiga kantong. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: Sarah is my best friend. She has long curly hair and bright eyes. She is cheerful and loves to sing. What is Sarah like?", options: ["Cheerful and loves to sing", "Quiet and shy", "Lazy and grumpy", "Serious and silent"], answer: 0, solution: "1. Pertanyaan menanyakan sifat Sarah. 2. Teks menulis Sarah ceria dan suka bernyanyi. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: The Komodo dragon is the largest lizard in the world. It lives on Komodo Island in Indonesia. It has sharp teeth and a strong tail. Where does the Komodo dragon live?", options: ["In Australia", "On Komodo Island in Indonesia", "In the Amazon forest", "In Africa"], answer: 1, solution: "1. Pertanyaan menanyakan tempat tinggal komodo. 2. Teks menulis komodo hidup di Pulau Komodo, Indonesia. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: My village is small and peaceful. Green rice fields surround the houses, and a clear river flows nearby. The air is fresh and cool. What surrounds the houses in the village?", options: ["Tall buildings", "Busy markets", "Green rice fields", "Wide deserts"], answer: 2, solution: "1. Pertanyaan menanyakan apa yang mengelilingi rumah-rumah di desa. 2. Teks menulis sawah hijau mengelilingi rumah-rumah itu. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: This dictionary is thick and heavy. It contains more than 50,000 English words with their meanings. The cover is red. What color is the dictionary's cover?", options: ["Blue", "Green", "Yellow", "Red"], answer: 3, solution: "1. Pertanyaan menanyakan warna sampul kamus. 2. Teks menulis sampulnya berwarna merah. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: My grandmother is seventy years old. She has grey hair and wears glasses. She is kind and tells wonderful stories. How old is the writer's grandmother?", options: ["Seventy years old", "Sixty years old", "Eighty years old", "Fifty years old"], answer: 0, solution: "1. Pertanyaan menanyakan umur nenek penulis. 2. Teks menulis neneknya berumur tujuh puluh tahun. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: Elephants are huge animals with long trunks and big ears. They eat grass and leaves. They are smart and live in groups. What do elephants eat?", options: ["Meat", "Grass and leaves", "Fish", "Insects"], answer: 1, solution: "1. Pertanyaan menanyakan makanan gajah. 2. Teks menulis gajah makan rumput dan dedaunan. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: How to Make Orange Juice. Ingredients: 3 oranges, 1 glass of water, 2 spoons of sugar, ice cubes. Steps: 1. Peel the oranges. 2. Squeeze the oranges. 3. Add water and sugar. 4. Stir well and add ice cubes. 5. Serve cold. What should we do after squeezing the oranges?", options: ["Peel the oranges", "Serve it hot", "Add water and sugar", "Add more oranges"], answer: 2, solution: "1. Pertanyaan menanyakan langkah setelah memeras jeruk. 2. Teks menulis langkah berikutnya adalah menambah air dan gula. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: How to Plant a Flower. You need: a small pot, soil, seeds, and water. Steps: 1. Fill the pot with soil. 2. Make a small hole in the soil. 3. Put the seeds in the hole. 4. Cover the seeds with soil. 5. Water the soil every day. What is the last step?", options: ["Fill the pot with soil", "Put the seeds in the hole", "Cover the seeds with soil", "Water the soil every day"], answer: 3, solution: "1. Pertanyaan menanyakan langkah terakhir menanam bunga. 2. Teks menulis langkah terakhir adalah menyiram tanah setiap hari. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: How to Cook Instant Noodles. Steps: 1. Boil 400 ml of water. 2. Put the noodles into the boiling water. 3. Cook for 3 minutes and stir. 4. Add the seasoning and mix well. 5. Serve while hot. How long should we cook the noodles?", options: ["3 minutes", "5 minutes", "10 minutes", "1 minute"], answer: 0, solution: "1. Pertanyaan menanyakan lama memasak mi. 2. Teks menulis masak selama 3 menit. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: How to Wash Your Hands. Steps: 1. Wet your hands with clean water. 2. Apply enough soap. 3. Rub your hands for 20 seconds. 4. Rinse with clean water. 5. Dry with a clean towel. What is the first step?", options: ["Apply soap", "Wet your hands with clean water", "Rub your hands", "Dry with a towel"], answer: 1, solution: "1. Pertanyaan menanyakan langkah pertama mencuci tangan. 2. Teks menulis langkah pertama adalah membasahi tangan dengan air bersih. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: How to Send an Email. Steps: 1. Open your email app. 2. Click the 'Compose' or 'New' button. 3. Type the recipient's address. 4. Write the subject and the message. 5. Click 'Send'. What do we do after opening the email app?", options: ["Click 'Send'", "Type the message", "Click the 'Compose' or 'New' button", "Close the app"], answer: 2, solution: "1. Pertanyaan menanyakan langkah setelah membuka aplikasi email. 2. Teks menulis langkah berikutnya adalah mengeklik tombol Compose atau New. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: How to Make a Paper Boat. Steps: 1. Take a sheet of paper. 2. Fold it in half. 3. Fold the top corners to the center. 4. Fold the bottom edges up. 5. Open the boat shape. What do we need to make a paper boat?", options: ["Glue and scissors", "Paint and brush", "A ruler and pencil", "A sheet of paper"], answer: 3, solution: "1. Pertanyaan menanyakan bahan untuk membuat perahu kertas. 2. Teks menulis kita membutuhkan selembar kertas. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the text: How to Charge Your Phone. Steps: 1. Connect the cable to your phone. 2. Plug the charger into the socket. 3. Wait until the battery is full. 4. Unplug the charger. What is the second step?", options: ["Plug the charger into the socket", "Connect the cable to your phone", "Wait for the battery", "Turn off the phone"], answer: 0, solution: "1. Pertanyaan menanyakan langkah kedua mengisi daya ponsel. 2. Teks menulis langkah kedua adalah mencolokkan charger ke stopkontak. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the text: How to Make Sweet Tea. Steps: 1. Boil some water. 2. Put a tea bag into a cup. 3. Pour the hot water into the cup. 4. Add sugar and stir. 5. Remove the tea bag and serve. What do we add to the tea?", options: ["Milk", "Sugar", "Lemon", "Honey"], answer: 1, solution: "1. Pertanyaan menanyakan apa yang ditambahkan ke teh. 2. Teks menulis tambahkan gula lalu aduk. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the text: How to Borrow a Book from the Library. Steps: 1. Find the book on the shelf. 2. Bring it to the librarian's desk. 3. Show your library card. 4. The librarian will stamp the due date. What must you show to the librarian?", options: ["Your ID card only", "Your student report", "Your library card", "Your money"], answer: 2, solution: "1. Pertanyaan menanyakan apa yang harus ditunjukkan ke pustakawan. 2. Teks menulis tunjukkan kartu perpustakaanmu. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the text: How to Fly a Kite. Steps: 1. Choose an open field. 2. Hold the kite against the wind. 3. Run forward and release the string slowly. 4. Pull the string gently to keep it up. Where should you fly a kite?", options: ["In a narrow alley", "Inside the house", "Under tall trees", "In an open field"], answer: 3, solution: "1. Pertanyaan menanyakan di mana sebaiknya bermain layang-layang. 2. Teks menulis pilihlah lapangan terbuka. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the story: One summer, the ant worked hard collecting food while the grasshopper sang all day. When winter came, the grasshopper was hungry, but the ant had plenty of food. The ant kindly shared some food with the grasshopper. What is the moral of the story?", options: ["We should work hard and prepare for the future", "We should sing all day", "We should sleep in summer", "We should never share food"], answer: 0, solution: "1. Pertanyaan menanyakan pesan moral cerita. 2. Semut yang bekerja keras punya makanan di musim dingin, sedangkan belalang yang bermalas-malasan kelaparan. 3. Jadi pesannya adalah kita harus bekerja keras dan bersiap untuk masa depan." },
    { q: "Read the story: The hare laughed at the slow tortoise and ran fast ahead. Feeling sure he would win, the hare took a nap under a tree. The tortoise kept walking and finally won the race. Why did the hare lose the race?", options: ["He was too slow", "He took a nap because he was overconfident", "He got lost", "He helped the tortoise"], answer: 1, solution: "1. Pertanyaan menanyakan alasan kelinci kalah. 2. Kelinci merasa pasti menang lalu tidur siang di bawah pohon. 3. Jadi ia kalah karena terlalu percaya diri dan tertidur." },
    { q: "Read the story: Timun Mas was a brave girl who lived with her mother. A giant wanted to eat her, so she ran away. She threw magic cucumber seeds, and they grew into a huge cucumber field that trapped the giant. How did Timun Mas defeat the giant?", options: ["She fought him with a sword", "She asked the villagers for help", "She threw magic cucumber seeds that trapped him", "She hid in a cave"], answer: 2, solution: "1. Pertanyaan menanyakan cara Timun Mas mengalahkan raksasa. 2. Teks menulis ia melempar biji mentimun ajaib yang tumbuh menjadi ladang mentimun raksasa dan menjebak raksasa. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the story: A little mouse woke up a sleeping lion. The lion was angry but let the mouse go. Later, the lion was caught in a net, and the mouse chewed the ropes to free him. How did the mouse help the lion?", options: ["It brought food to the lion", "It scared the hunters away", "It called other animals", "It chewed the ropes of the net"], answer: 3, solution: "1. Pertanyaan menanyakan cara tikus menolong singa. 2. Teks menulis tikus menggerogoti tali jaring hingga singa bebas. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the story: Darmi was a lazy girl who was rude to her poor mother. One day her mother prayed, and Darmi slowly turned into stone. Her tears kept flowing even after she became stone. What happened to Darmi?", options: ["She turned into stone", "She became a princess", "She ran away from home", "She found a treasure"], answer: 0, solution: "1. Pertanyaan menanyakan apa yang terjadi pada Darmi. 2. Teks menulis Darmi perlahan berubah menjadi batu. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the story: A shepherd boy often shouted 'Wolf! Wolf!' just for fun. The villagers came to help, but there was no wolf. When a real wolf came, nobody believed him. What is the moral of the story?", options: ["Always be brave", "Do not lie, or people will not trust you", "Wolves are dangerous", "Shepherds are lazy"], answer: 1, solution: "1. Pertanyaan menanyakan pesan moral cerita. 2. Anak gembala sering berbohong sehingga saat serigala benar-benar datang tak ada yang percaya. 3. Jadi pesannya adalah jangan berbohong agar orang tetap percaya padamu." },
    { q: "Read the story: A farmer's donkey fell into a deep well. The farmer could not pull it out, so he decided to bury it. But as soil fell on its back, the donkey shook it off and stepped up. Finally, it jumped out of the well. How did the donkey get out of the well?", options: ["The farmer pulled it with a rope", "It climbed a ladder", "It shook off the soil and stepped up until it could jump out", "It waited for the rain"], answer: 2, solution: "1. Pertanyaan menanyakan cara keledai keluar dari sumur. 2. Teks menulis keledai menggoyangkan tanah dari punggungnya dan menginjaknya hingga bisa melompat keluar. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the story: Sangkuriang wanted to marry Dayang Sumbi, not knowing she was his mother. Dayang Sumbi asked him to build a huge boat in one night. When he almost finished, she made the morning come early, so he failed and kicked the boat, which became a mountain. Why did Sangkuriang fail to finish the boat?", options: ["He was too tired", "He forgot the wood", "The boat was too heavy", "Dayang Sumbi made the morning come early"], answer: 3, solution: "1. Pertanyaan menanyakan alasan Sangkuriang gagal. 2. Teks menulis Dayang Sumbi membuat pagi datang lebih awal sehingga ia gagal. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the story: A dog carried a bone across a bridge. In the water, he saw his reflection holding a bigger bone. He opened his mouth to grab it, and his own bone fell into the river. Why did the dog lose his bone?", options: ["He was greedy and tried to grab the reflection's bone", "A bigger dog stole it", "He gave it to a friend", "It was too heavy"], answer: 0, solution: "1. Pertanyaan menanyakan alasan anjing kehilangan tulangnya. 2. Anjing itu serakah dan membuka mulut untuk merebut tulang bayangannya sendiri. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the story: A woodcutter dropped his axe into the river. A fairy offered him a golden axe, but he said it was not his. She then offered a silver axe, and he refused again. Finally she gave him his own iron axe, plus the golden and silver ones as a reward. Why did the woodcutter receive the golden and silver axes?", options: ["He bought them", "Because he was honest", "He found them in the forest", "The fairy felt sorry"], answer: 1, solution: "1. Pertanyaan menanyakan alasan penebang kayu menerima kapak emas dan perak. 2. Ia jujur menolak kapak yang bukan miliknya hingga peri memberinya hadiah. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the announcement: The school library will be closed on Friday for cleaning. It will open again on Saturday morning. When will the library open again?", options: ["On Thursday", "On Friday", "On Saturday morning", "On Sunday"], answer: 2, solution: "1. Pertanyaan menanyakan kapan perpustakaan buka lagi. 2. Pengumuman menulis perpustakaan tutup hari Jumat dan buka lagi Sabtu pagi. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the announcement: All students must gather in the school yard at 7 a.m. tomorrow for the Independence Day rehearsal. Wear your sports uniform. What must the students wear?", options: ["The scout uniform", "The batik uniform", "Formal clothes", "Their sports uniform"], answer: 3, solution: "1. Pertanyaan menanyakan pakaian yang harus dipakai siswa. 2. Pengumuman menulis kenakan seragam olahraga. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the announcement: The English speech contest will be held in the hall on 15 October. Registration closes on 10 October at the OSIS room. Where can students register for the contest?", options: ["At the OSIS room", "In the library", "At the canteen", "In the classroom"], answer: 0, solution: "1. Pertanyaan menanyakan tempat pendaftaran lomba. 2. Pengumuman menulis pendaftaran di ruang OSIS. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the announcement: Due to heavy rain, today's football practice is moved to the indoor hall. Practice starts at the usual time, 4 p.m. Why is the football practice moved?", options: ["Because the coach is sick", "Because of heavy rain", "Because of a match", "Because the field is booked"], answer: 1, solution: "1. Pertanyaan menanyakan alasan latihan dipindah. 2. Pengumuman menulis karena hujan deras. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the advertisement: Fresh Juice Bar! Buy 2 get 1 free every weekend. Open 10 a.m. to 9 p.m. at City Mall, 2nd floor. When can customers get the buy 2 get 1 free promo?", options: ["Every Monday", "Every day", "Every weekend", "Only at night"], answer: 2, solution: "1. Pertanyaan menanyakan kapan promo beli 2 gratis 1 berlaku. 2. Iklan menulis promo berlaku setiap akhir pekan. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the advertisement: Learn English Fast! Join our 3-month course. Only Rp150,000 per month. Free placement test. Call 0812-3456-7890. How much is the course fee per month?", options: ["Rp100,000", "Rp300,000", "Rp50,000", "Rp150,000"], answer: 3, solution: "1. Pertanyaan menanyakan biaya kursus per bulan. 2. Iklan menulis hanya Rp150.000 per bulan. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the advertisement: New Laptop Sale! Discount up to 30%. Free mouse and bag for the first 50 buyers. Visit Techno Store this week. What do the first 50 buyers get?", options: ["A free mouse and bag", "A free printer", "Extra discount 50%", "A free tablet"], answer: 0, solution: "1. Pertanyaan menanyakan hadiah untuk 50 pembeli pertama. 2. Iklan menulis mouse dan tas gratis untuk 50 pembeli pertama. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the advertisement: Swimming Course for Kids! Every Saturday and Sunday, 8 a.m. at Tirta Swimming Pool. Coach: Mr. Budi. Register now, limited seats! When is the swimming course held?", options: ["Every Monday", "Every Saturday and Sunday", "Every Friday", "Every day"], answer: 1, solution: "1. Pertanyaan menanyakan jadwal kursus renang. 2. Iklan menulis setiap Sabtu dan Minggu. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the notice: Please keep silent. Exam in progress. What does the notice mean?", options: ["You may talk loudly", "You must sing a song", "You must not make noise", "You must leave the room"], answer: 2, solution: "1. Pertanyaan menanyakan arti pemberitahuan. 2. Pemberitahuan menulis harap diam karena ujian sedang berlangsung. 3. Jadi artinya kita tidak boleh membuat kegaduhan." },
    { q: "Read the caution sign: Wet floor. Watch your step. What should people do?", options: ["Run quickly", "Sit on the floor", "Dance on the floor", "Walk carefully"], answer: 3, solution: "1. Pertanyaan menanyakan apa yang harus dilakukan orang. 2. Peringatan menulis lantai basah, awas langkahmu. 3. Jadi orang harus berjalan dengan hati-hati." },
    { q: "Read the prohibition sign: No parking here. What does the sign prohibit?", options: ["Parking vehicles here", "Driving fast", "Honking the horn", "Entering the building"], answer: 0, solution: "1. Pertanyaan menanyakan apa yang dilarang rambu itu. 2. Rambu menulis dilarang parkir di sini. 3. Jadi yang dilarang adalah memarkir kendaraan di sini." },
    { q: "Read the notice: Please queue in line. What should people do?", options: ["Push each other", "Stand in an orderly line", "Skip the line", "Sit on the floor"], answer: 1, solution: "1. Pertanyaan menanyakan apa yang harus dilakukan orang. 2. Pemberitahuan menulis harap antre berbaris. 3. Jadi orang harus berdiri dalam barisan yang tertib." },
    { q: "Read the label: Choco Milk Drink. Ingredients: fresh milk, cocoa, sugar. Net volume: 250 ml. Best before: see the bottom of the pack. Shake well before drinking. What should you do before drinking it?", options: ["Heat it first", "Add more sugar", "Shake it well", "Freeze it"], answer: 2, solution: "1. Pertanyaan menanyakan apa yang harus dilakukan sebelum meminumnya. 2. Label menulis kocok dulu sebelum diminum. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the label: Cough Syrup Herba. Dosage: adults 2 spoons, 3 times a day; children 1 spoon, 3 times a day. Shake well. Keep away from children. How much syrup should a child take each time?", options: ["3 spoons", "2 spoons", "Half a spoon", "1 spoon"], answer: 3, solution: "1. Pertanyaan menanyakan dosis untuk anak setiap kali minum. 2. Label menulis anak 1 sendok, 3 kali sehari. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the label: Instant Coffee Pagi. Composition: coffee, sugar, creamer. Net weight: 20 g per sachet. Expired date: 12-2027. What is in the coffee sachet?", options: ["Coffee, sugar, and creamer", "Milk and chocolate", "Tea and sugar", "Coffee only"], answer: 0, solution: "1. Pertanyaan menanyakan isi sachet kopi. 2. Label menulis komposisi: kopi, gula, krimer. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the invitation: Dear Lisa, You are invited to my 14th birthday party! Day: Saturday, 20 June. Time: 4 p.m. Place: My house, Jl. Melati No. 10. Love, Dina. When is Dina's birthday party?", options: ["Sunday, 20 June", "Saturday, 20 June", "Saturday, 10 June", "Friday, 20 June"], answer: 1, solution: "1. Pertanyaan menanyakan kapan pesta ulang tahun Dina. 2. Undangan menulis hari Sabtu, 20 Juni. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "Read the invitation: To all class 8A students. We will have a farewell party for Mr. Ando on Friday at 2 p.m. in the classroom. Please come on time. What is the purpose of the party?", options: ["To celebrate a birthday", "To welcome a new teacher", "To say goodbye to Mr. Ando", "To celebrate graduation"], answer: 2, solution: "1. Pertanyaan menanyakan tujuan pesta. 2. Undangan menulis pesta perpisahan untuk Pak Ando. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Read the invitation: Dear Mr. Hartono, We invite you to the school art exhibition on Monday, 5 May, 9 a.m. to 12 p.m. at the school hall. Sincerely, Art Club. Where will the art exhibition be held?", options: ["In the classroom", "At the city museum", "In the library", "At the school hall"], answer: 3, solution: "1. Pertanyaan menanyakan tempat pameran seni. 2. Undangan menulis di aula sekolah. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Read the message: Hi Tom! I'm having a small dinner at my place this Saturday at 7 p.m. Hope you can come! Love, Riko. What time is Riko's dinner?", options: ["7 p.m.", "7 a.m.", "8 p.m.", "6 p.m."], answer: 0, solution: "1. Pertanyaan menanyakan jam makan malam Riko. 2. Pesan menulis jam 7 malam hari Sabtu. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Read the card: Get well soon, Grandma! We hope you recover quickly and can play with us again. Love, your grandchildren. What kind of card is this?", options: ["A birthday card", "A get-well-soon card", "A thank-you card", "An invitation card"], answer: 1, solution: "1. Pertanyaan menanyakan jenis kartu itu. 2. Kartu berisi harapan agar nenek cepat sembuh. 3. Jadi itu kartu semoga lekas sembuh." },
    { q: "The firefighter was very brave when he saved the child from the fire. The word brave is closest in meaning to ....", options: ["afraid", "weak", "courageous", "careful"], answer: 2, solution: "1. Kata brave berarti berani. 2. Kata yang maknanya paling dekat adalah courageous yang juga berarti berani. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Let's begin the meeting at 8 o'clock. The word begin is closest in meaning to ....", options: ["finish", "delay", "cancel", "start"], answer: 3, solution: "1. Kata begin berarti mulai. 2. Kata yang maknanya paling dekat adalah start yang juga berarti mulai. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "The garden is beautiful in spring. The word beautiful is closest in meaning to ....", options: ["lovely", "ugly", "plain", "dark"], answer: 0, solution: "1. Kata beautiful berarti indah. 2. Kata yang maknanya paling dekat adalah lovely yang juga berarti indah. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "The teacher was angry because the students were noisy. The word angry is closest in meaning to ....", options: ["calm", "furious", "sad", "glad"], answer: 1, solution: "1. Kata angry berarti marah. 2. Kata yang maknanya paling dekat adalah furious yang juga berarti sangat marah. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "He gave a quick answer to the question. The word quick is closest in meaning to ....", options: ["slow", "late", "fast", "quiet"], answer: 2, solution: "1. Kata quick berarti cepat. 2. Kata yang maknanya paling dekat adalah fast yang juga berarti cepat. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Mr. Tanto is a rich businessman. The word rich is closest in meaning to ....", options: ["poor", "lazy", "kind", "wealthy"], answer: 3, solution: "1. Kata rich berarti kaya. 2. Kata yang maknanya paling dekat adalah wealthy yang juga berarti kaya. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Dolphins are smart animals. The word smart is closest in meaning to ....", options: ["clever", "stupid", "slow", "weak"], answer: 0, solution: "1. Kata smart berarti pintar. 2. Kata yang maknanya paling dekat adalah clever yang juga berarti pintar. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "The opposite of hot is ....", options: ["warm", "cold", "spicy", "sunny"], answer: 1, solution: "1. Pertanyaan menanyakan lawan kata hot. 2. Hot berarti panas, lawannya adalah cold yang berarti dingin. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "The opposite of arrive is ....", options: ["come", "reach", "leave", "enter"], answer: 2, solution: "1. Pertanyaan menanyakan lawan kata arrive. 2. Arrive berarti tiba, lawannya adalah leave yang berarti pergi. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "The opposite of clean is ....", options: ["tidy", "clear", "fresh", "dirty"], answer: 3, solution: "1. Pertanyaan menanyakan lawan kata clean. 2. Clean berarti bersih, lawannya adalah dirty yang berarti kotor. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "The opposite of success is ....", options: ["failure", "victory", "luck", "prize"], answer: 0, solution: "1. Pertanyaan menanyakan lawan kata success. 2. Success berarti keberhasilan, lawannya adalah failure yang berarti kegagalan. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "The opposite of win is ....", options: ["beat", "lose", "gain", "score"], answer: 1, solution: "1. Pertanyaan menanyakan lawan kata win. 2. Win berarti menang, lawannya adalah lose yang berarti kalah. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "The opposite of modern is ....", options: ["new", "recent", "old-fashioned", "stylish"], answer: 2, solution: "1. Pertanyaan menanyakan lawan kata modern. 2. Modern berarti kekinian, lawannya adalah old-fashioned yang berarti kuno. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "The opposite of polite is ....", options: ["kind", "friendly", "gentle", "rude"], answer: 3, solution: "1. Pertanyaan menanyakan lawan kata polite. 2. Polite berarti sopan, lawannya adalah rude yang berarti kasar. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "A person who repairs cars is called a ....", options: ["mechanic", "pilot", "farmer", "nurse"], answer: 0, solution: "1. Pertanyaan menanyakan sebutan orang yang memperbaiki mobil. 2. Orang yang memperbaiki mobil disebut mechanic. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "The library is very quiet. Everyone must keep silent. The word quiet means ....", options: ["noisy", "not noisy", "crowded", "bright"], answer: 1, solution: "1. Pertanyaan menanyakan arti kata quiet dalam kalimat. 2. Perpustakaan itu sangat quiet dan semua orang harus diam. 3. Jadi quiet berarti tidak berisik." },
    { q: "She saved some money every month so she could buy a new bag. The word saved here means ....", options: ["spent", "lost", "kept for the future", "borrowed"], answer: 2, solution: "1. Pertanyaan menanyakan arti kata saved dalam kalimat. 2. Ia saved uang setiap bulan agar bisa membeli tas baru. 3. Jadi saved di sini berarti menyimpan untuk masa depan." },
    { q: "The mountain climbers felt exhausted after the long hike. The word exhausted means ....", options: ["excited", "happy", "energetic", "very tired"], answer: 3, solution: "1. Pertanyaan menanyakan arti kata exhausted. 2. Para pendaki merasa exhausted setelah pendakian panjang. 3. Jadi exhausted berarti sangat lelah." },
    { q: "A place where books are kept and borrowed is a ....", options: ["library", "market", "hospital", "station"], answer: 0, solution: "1. Pertanyaan menanyakan sebutan tempat menyimpan dan meminjam buku. 2. Tempat menyimpan dan meminjam buku adalah library. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Bagas: In my opinion, reading books is more fun than playing games. Dito: I couldn't agree more. Books open our minds. What does Dito express?", options: ["Disagreement", "Agreement", "An apology", "A suggestion"], answer: 1, solution: "1. Dito berkata I could not agree more. 2. Ungkapan itu berarti ia sangat setuju dengan pendapat Bagas. 3. Jadi Dito menyatakan persetujuan." },
    { q: "Sinta: What do you think about online learning? Rudi: I think it's practical, but it needs a good internet connection. Rudi is ....", options: ["refusing an offer", "asking for help", "giving his opinion", "making a promise"], answer: 2, solution: "1. Rudi menjawab pertanyaan Sinta dengan pendapatnya tentang belajar online. 2. Ia tidak bertanya atau menolak, melainkan menyampaikan opini. 3. Jadi Rudi sedang memberikan pendapatnya." },
    { q: "Ayu: The new school canteen is great, don't you think so? Bimo: I'm afraid I disagree. The food is too expensive. Bimo expresses ....", options: ["agreement", "satisfaction", "pleasure", "disagreement"], answer: 3, solution: "1. Ayu memuji kantin baru, lalu Bimo berkata I am afraid I disagree. 2. Ungkapan itu berarti ia tidak setuju. 3. Jadi Bimo menyatakan ketidaksetujuan." },
    { q: "Which sentence asks for someone's opinion?", options: ["What's your opinion about the new park?", "The new park is beautiful.", "I love the new park.", "Let's go to the new park."], answer: 0, solution: "1. Pertanyaan menanyakan kalimat yang meminta pendapat. 2. Hanya opsi pertama yang menanyakan pendapat tentang taman baru. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "Rina: I believe our team will win the match. Doni: I hope so too. Doni's response shows ....", options: ["doubt", "agreement", "refusal", "anger"], answer: 1, solution: "1. Rina yakin timnya akan menang, Doni menjawab I hope so too. 2. Respons itu menunjukkan ia sependapat dengan Rina. 3. Jadi jawaban Doni menunjukkan persetujuan." },
    { q: "Lina won the English speech contest. What is the best thing to say to her?", options: ["Good luck next time.", "Better luck tomorrow.", "Congratulations on winning the contest!", "I'm sorry to hear that."], answer: 2, solution: "1. Lina memenangkan lomba pidato bahasa Inggris. 2. Ucapan yang tepat untuk pemenang adalah selamat atas kemenangannya. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "Your friend looks great in his new jacket. You say: ....", options: ["That's a terrible jacket.", "You look awful today.", "I don't like your jacket.", "You look great in that jacket!"], answer: 3, solution: "1. Temanmu terlihat bagus memakai jaket baru. 2. Kalimat yang tepat adalah pujian tentang penampilannya. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Andi got the highest score in math. Sinta says: Wow, you're amazing at math! Sinta is ....", options: ["giving a compliment", "asking for help", "making a promise", "giving advice"], answer: 0, solution: "1. Sinta berkata Wow, kamu hebat dalam matematika kepada Andi. 2. Itu adalah pujian atas nilai tertingginya. 3. Jadi Sinta sedang memberi pujian." },
    { q: "You see your friend carrying many heavy books. You say: ....", options: ["That's your problem.", "Let me help you carry those books.", "Put them down now.", "Why do you bring so many?"], answer: 1, solution: "1. Temanmu membawa banyak buku berat. 2. Tawaran bantuan yang sopan adalah menawarkan membawakan buku-bukunya. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "It's very hot today. The best suggestion is: ....", options: ["Let's stay in the sun.", "Let's wear thick jackets.", "Let's buy some cold drinks.", "Let's run around the field."], answer: 2, solution: "1. Hari ini sangat panas. 2. Saran yang paling tepat adalah membeli minuman dingin. 3. Jadi jawabannya adalah opsi ketiga." },
    { q: "You don't understand the math homework. You say to your friend: ....", options: ["Do it yourself.", "I can do it alone.", "Don't bother me.", "Could you help me with this homework, please?"], answer: 3, solution: "1. Kamu tidak paham PR matematika. 2. Cara sopan meminta bantuan adalah bertanya bisakah temanmu membantumu. 3. Jadi jawabannya adalah opsi keempat." },
    { q: "Your friend lent you her pen. You say: ....", options: ["Thank you very much for the pen.", "Give it back now.", "It's just a pen.", "I don't need it."], answer: 0, solution: "1. Temanmu meminjamkan pulpennya. 2. Respons yang tepat adalah mengucapkan terima kasih. 3. Jadi jawabannya adalah opsi pertama." },
    { q: "You stepped on your friend's foot. You say: ....", options: ["Watch where you walk!", "I'm sorry, I didn't mean it.", "It's your fault.", "Be careful next time."], answer: 1, solution: "1. Kamu menginjak kaki temanmu. 2. Respons yang tepat adalah meminta maaf dengan tulus. 3. Jadi jawabannya adalah opsi kedua." },
    { q: "A: Would you like some tea? B gives a polite acceptance: ....", options: ["No, I hate tea.", "Tea is bad.", "Yes, please. That would be lovely.", "Go away."], answer: 2, solution: "1. A menawarkan teh dan B menerima dengan sopan. 2. Penerimaan yang sopan adalah Yes, please yang berarti ya dengan senang hati. 3. Jadi jawabannya adalah opsi ketiga." }
  ]
};
